#!/usr/bin/env python3
"""Parse a JSON file, extract categorical columns, and output SQL INSERT statements."""

import json
import sys


def infer_categorical(rows, max_unique_ratio=0.5, max_unique_abs=50):
    """Identify categorical columns: low cardinality or string-typed."""
    if not rows:
        return []
    columns = list(rows[0].keys())
    categorical = []
    for col in columns:
        values = [row.get(col) for row in rows]
        nunique = len(set(str(v) for v in values))
        # Treat as categorical if string type with low cardinality
        all_str = all(isinstance(v, str) or v is None for v in values)
        if all_str and (nunique <= max_unique_abs or nunique / len(values) < max_unique_ratio):
            categorical.append(col)
    return categorical


def sql_escape(value):
    """Escape a value for SQL."""
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    if isinstance(value, (int, float)):
        return str(value)
    return "'" + str(value).replace("'", "''") + "'"


def generate_inserts(table_name, rows, columns):
    """Generate SQL INSERT statements for the given rows and columns."""
    col_list = ", ".join(columns)
    statements = []
    for row in rows:
        values = ", ".join(sql_escape(row.get(col)) for col in columns)
        statements.append(f"INSERT INTO {table_name} ({col_list}) VALUES ({values});")
    return statements


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <json_file> [table_name]", file=sys.stderr)
        sys.exit(1)

    json_file = sys.argv[1]
    table_name = sys.argv[2] if len(sys.argv) > 2 else "data"

    with open(json_file) as f:
        data = json.load(f)

    # Accept either a list of objects or a single object
    if isinstance(data, dict):
        data = [data]
    if not isinstance(data, list) or not all(isinstance(row, dict) for row in data):
        print("Error: JSON must be a list of objects or a single object.", file=sys.stderr)
        sys.exit(1)

    categorical_cols = infer_categorical(data)
    if not categorical_cols:
        print("No categorical columns found.", file=sys.stderr)
        sys.exit(0)

    print(f"-- Categorical columns detected: {', '.join(categorical_cols)}")
    print(f"-- Total rows: {len(data)}\n")

    for stmt in generate_inserts(table_name, data, categorical_cols):
        print(stmt)


if __name__ == "__main__":
    main()

